from pathlib import Path
import json,hashlib,shutil,re,markdown
R=Path.cwd();O=R/'doc/research/possible-bodies';E=R/'doc/space/iso-torus-gyroid-2026-09-15';run=R/'ada_run/iso-torus-gyroid-review-2026-09-15';M='ISO_TorusGyroid'
r=json.loads((run/'run.json').read_text());assert r['exit']==0 and r['sources_unchanged'];assert all(hashlib.sha256((R/p).read_bytes()).hexdigest()==h for p,h in r['source_sha256'].items())
